const test=require('node:test'),assert=require('node:assert/strict');
async function setup(left='wizard',right='zombie',length=24){
 const {syncEncounter}=await import('../outbreak-simulation.mjs');
 const graph={nodes:{'a#0':{x:0,y:0,z:0},'a#1':{x:8,y:0,z:0},'b#0':{x:16,y:0,z:0},'b#1':{x:length,y:0,z:0}},adj:{'a#0':[{id:'a#1',cost:8}],'a#1':[{id:'a#0',cost:8},{id:'b#0',cost:8}],'b#0':[{id:'a#1',cost:8},{id:'b#1',cost:length-16}],'b#1':[{id:'b#0',cost:length-16}]},signature:'line',hubs:{}};
 const board={id:'actor-test',instances:[{instanceId:'a',cardId:'a',cardRevision:1},{instanceId:'b',cardId:'b',cardRevision:1}],cards:{'a@1':{recipe:{seed:41,agents:{archetype:left,count:1}}},'b@1':{recipe:{seed:63,agents:{archetype:right,count:1}}}}};
 const world=syncEncounter({id:board.id,seconds:0,entities:{'place/a':{id:'place/a',active:true,affinities:{}},'place/b':{id:'place/b',active:true,affinities:{}}},groups:{}},board,graph);
 const [a,b]=Object.values(world.actors);a.position={...graph.nodes['a#0']};b.position={...graph.nodes['b#1']};return {world,graph,board,a,b};
}
test('Fireballs have windup, travel, mana cost, splash and persistent burning through the common damage resolver',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{world,graph,a,b}=await setup();b.hp=b.maxHp=30;b.speed=0;let w=advanceEncounter(world,graph,1);assert(w.encounter.projectiles.length>0);assert.equal(w.actors[b.id].hp,30);assert(w.actors[a.id].mana<8);w=advanceEncounter(w,graph,1);assert(w.actors[b.id].hp<30);assert(w.actors[b.id].burning);const hp=w.actors[b.id].hp;w=advanceEncounter(w,graph,.5);assert(w.actors[b.id].hp<hp);assert.equal(w.encounter.casts,1);});
test('Fast swept projectiles hit intervening bodies and thin obstacles rather than tunnelling',async()=>{const {sphereHit,environmentHit}=await import('../actor-projectiles.mjs');assert(sphereHit({x:0,y:1,z:0},{x:100,y:1,z:0},{x:50,y:1,z:0},.3)<.5);const g={signature:'wall',obstacles:[{kind:'box',x:40,z:0,w:.1,d:5,angle:0}]};const t=environmentHit(g,{x:0,y:1,z:0},{x:100,y:1,z:0},.25);assert(t>.39&&t<.41);});
test('A wall or raised terrain blocks fireballs even when a walking route exists',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{world,graph,b}=await setup();b.speed=0;world.actors[Object.keys(world.actors)[0]].speed=0;graph.obstacles=[{kind:'box',x:12,z:0,w:1,d:10,angle:0}];const w=advanceEncounter(world,graph,8);assert.equal(w.encounter.casts,0);assert.equal(w.actors[b.id].hp,b.hp);const {environmentHit}=await import('../actor-projectiles.mjs');assert.notEqual(environmentHit({signature:'hill',heightAt:x=>x>5?2:0},{x:0,y:1,z:0},{x:10,y:1,z:0}),null);});
test('Projectiles and pending AI replay identically across save/reload and step batching',async()=>{const {advanceEncounter,syncEncounter}=await import('../outbreak-simulation.mjs'),{world,graph,board,b}=await setup();b.hp=b.maxHp=80;b.speed=0;const halfway=advanceEncounter(world,graph,1.25);assert(halfway.encounter.projectiles.length);const reloaded=syncEncounter(JSON.parse(JSON.stringify(halfway)),board,graph);assert.deepEqual(advanceEncounter(reloaded,graph,8.75),advanceEncounter(world,graph,10));});
test('Different nations are neutral until an explicit relation makes armed actors fight; a treaty cancels windups',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{setAffinities}=await import('../world-model.mjs'),{setRelationship}=await import('../world-relations.mjs');let {world,graph,a,b}=await setup('wizard','wizard');world=setAffinities(world,'place/a','national',['Ember']);world=setAffinities(world,'place/b','national',['River']);const groups=Object.keys(world.groups);assert.equal(advanceEncounter(world,graph,5).encounter.casts,0);world=setRelationship(world,...groups,'hostile');const fight=advanceEncounter(world,graph,1);assert(fight.encounter.casts>0);const treaty=setRelationship(world,...groups,'allied');assert.equal(advanceEncounter(treaty,graph,5).encounter.casts,0);assert.throws(()=>setRelationship(world,groups[0],groups[0],'hostile'));});
test('Rabbits flee generic predators and zombies; unreachable escape paths never teleport them',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs');for(const predator of ['wolf','zombie']){const {world,graph,a,b}=await setup('rabbit',predator,30);a.position={x:15,y:0,z:0};b.position={x:20,y:0,z:0};const w=advanceEncounter(world,graph,1);assert.equal(w.actors[a.id].intent,'fleeing');assert(w.actors[a.id].position.x<15);assert.equal(w.actors[a.id].position.z,0);}});
test('Yuka heap search resumes after serialization, rejects disconnected regions and cancels stale topology',async()=>{const {beginRoute,stepRoute}=await import('../world-navigation.mjs');const nodes={},adj={};for(let i=0;i<600;i++){nodes['n'+i]={x:i,y:0,z:0};adj['n'+i]=[...(i?[{id:'n'+(i-1),cost:1}]:[]),...(i<599?[{id:'n'+(i+1),cost:1}]:[])];}const graph={nodes,adj,signature:'long'};let job=beginRoute(graph,nodes.n0,nodes.n599);assert.equal(stepRoute(graph,job,32),32);assert.equal(job.status,'searching');job=JSON.parse(JSON.stringify(job));while(job.status==='searching')stepRoute(graph,job,32);assert.equal(job.result.distance,599);const stale=beginRoute(graph,nodes.n0,nodes.n599);stepRoute({...graph,signature:'changed'},stale,32);assert.equal(stale.status,'cancelled');const split={nodes:{a:nodes.n0,b:nodes.n599},adj:{a:[],b:[]},signature:'split'};assert.equal(beginRoute(split,split.nodes.a,split.nodes.b).status,'blocked');});
test('Large actor loads obey fixed decision and search budgets and retain unique identities',async()=>{const {spawnActors,advanceEncounter}=await import('../outbreak-simulation.mjs'),{SIMULATION_LIMITS}=await import('../actor-catalog.mjs');let {world,graph,board}=await setup('broom-elder','zombie');for(const id of ['a','b']){for(let i=0;i<7;i++)world=spawnActors(world,board,graph,id,32);world=spawnActors(world,board,graph,id,31);}assert.equal(Object.keys(world.actors).length,512);const w=advanceEncounter(world,graph,.25);assert(w.encounter.metrics.decisions<=SIMULATION_LIMITS.decisionsPerTick);assert(w.encounter.metrics.pathExpansions<=SIMULATION_LIMITS.pathExpansionsPerTick);assert.throws(()=>spawnActors(w,board,graph,'a',1),/512/);});
test('Wizard and rabbit generators place through the actual terrain and collision pipeline',async()=>{const {outbreakRecipe}=await import('../outbreak-scenes.mjs'),{planSettlementPreset}=await import('../settlement-layout.js'),{syncWorld}=await import('../world-model.mjs'),{worldNavigation}=await import('../world-navigation.mjs'),{syncEncounter}=await import('../outbreak-simulation.mjs'),fs=require('node:fs'),path=require('node:path');const root=path.join(__dirname,'..'),assetIndex=JSON.parse(fs.readFileSync(path.join(root,'domestic-assets/index.json')));const entries=[{type:'wizard',preset:'apprentice',seed:41,q:0,r:0},{type:'rabbits',preset:'grove',seed:63,q:0,r:1}],cards=entries.map((e,i)=>({id:'c'+i,type:e.type,revision:1,cells:[{q:0,r:0}],rendition:{meshes:[]},recipe:outbreakRecipe(e.type,e.preset,e.seed),capabilities:{}}));const site=planSettlementPreset({cards,entries,assetIndex,dimensions:{'tree-standing':{w:3,d:3}},boardId:'new-scenes',requireEconomy:false});assert.equal(site.status,'ready',JSON.stringify(site.warnings));const world=syncEncounter(syncWorld(site.board,site.assembly),site.board,worldNavigation(site.economy));assert.equal(Object.values(world.actors).filter(a=>a.archetype==='wizard').length,1);assert.equal(Object.values(world.actors).filter(a=>a.archetype==='rabbit').length,8);});

test('A peace treaty clears remembered retaliation without recalling physical projectiles',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{setAffinities}=await import('../world-model.mjs'),{setRelationship}=await import('../world-relations.mjs');let {world,graph,a,b}=await setup('broom-elder','broom-elder');a.position={x:10,y:0,z:0};b.position={x:11,y:0,z:0};world=setAffinities(world,'place/a','national',['Ember']);world=setAffinities(world,'place/b','national',['River']);const groups=Object.keys(world.groups);world=setRelationship(world,...groups,'hostile');const fight=advanceEncounter(world,graph,1);assert(fight.encounter.hits>0);const treaty=setRelationship(fight,...groups,'neutral'),peace=advanceEncounter(treaty,graph,3);assert.equal(peace.encounter.hits,fight.encounter.hits);assert(Object.values(peace.actors).every(a=>!a.attackerId));});

test('Authored wizard and wildlife matchups resolve combat on generated terrain and connected paths',async()=>{const fixture=require('./outbreak-fixture.cjs'),{advanceEncounter}=await import('../outbreak-simulation.mjs');const cases=[['zombies','horde','wizard','apprentice'],['rabbits','grove','rabbits','predator']];for(const [left,lp,right,rp]of cases){const entries=[{type:left,preset:lp,seed:41,q:0,r:0},{type:right,preset:rp,seed:63,q:0,r:1}];const {world,graph}=await fixture('scouts',entries),w=advanceEncounter(world,graph,240);assert(w.encounter.hits>0,left+' '+right+' must meet on real paths');if(right==='wizard')assert(w.encounter.casts>0);else assert(w.encounter.consumed>0);}});

test('A treaty permits in-flight collateral damage without restarting hostilities',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{setAffinities}=await import('../world-model.mjs'),{setRelationship}=await import('../world-relations.mjs');let {world,graph}=await setup('wizard','wizard');world=setAffinities(world,'place/a','national',['Ember']);world=setAffinities(world,'place/b','national',['River']);const groups=Object.keys(world.groups);world=setRelationship(world,...groups,'hostile');const flight=advanceEncounter(world,graph,1);assert(flight.encounter.projectiles.length>0);const peace=advanceEncounter(setRelationship(flight,...groups,'allied'),graph,6);assert.equal(peace.encounter.casts,flight.encounter.casts);assert(peace.encounter.hits>flight.encounter.hits);});
